/**
 * Emits typed `defineEvents` modules from the channel IR — the events
 * counterpart of `emitter.ts`. Generated files use the same hand-written
 * style (`defineEvents` / `subscribe` / `publish` / `P`) so they stay
 * readable, diffable and editable.
 */

import type { ChannelGroupIR, ChannelIR, EventsIR } from './model.js';
import type { ParamIR } from './openapi.js';
import {
  clamp,
  emitKind,
  escapeComment,
  formatArgs,
  schemaConstraintArgs,
} from './emitter.js';
import type { EmittedFile, EmitOptions } from './emitter.js';

export function emitEvents(ir: EventsIR, options: EmitOptions = {}): EmittedFile[] {
  const importFrom = options.importFrom ?? 'contractful-ts';
  const files: EmittedFile[] = [];
  const indexExports: { constName: string; file: string }[] = [];

  for (const group of ir.groups) {
    if (group.channels.length === 0) continue;

    const maxPerFile = options.maxPerFile ?? 0;
    const chunks =
      maxPerFile > 0 ? chunk(group.channels, maxPerFile) : [group.channels];

    chunks.forEach((channels, i) => {
      const multi = chunks.length > 1;
      const suffix = multi ? `-part-${i + 1}` : '';
      const constName = group.constName + (multi ? `Part${i + 1}` : '');
      const fileName = group.fileName.replace(/\.ts$/, `${suffix}.ts`);

      files.push({
        path: fileName,
        content: emitEventsFile(ir, group.name, constName, channels, importFrom, options),
      });
      indexExports.push({ constName, file: fileName.replace(/\.ts$/, '') });
    });
  }

  if ((options.emitIndex ?? true) && indexExports.length > 0) {
    files.push({
      path: 'index.ts',
      content: [
        `// Auto-generated by contractful-gen from ${originLabel(options.specOrigin)} — DO NOT EDIT.`,
        ...indexExports.map((entry) => `export * from './${entry.file}.js';`),
        '',
      ].join('\n'),
    });
  }

  return files;
}

function emitEventsFile(
  ir: EventsIR,
  groupName: string,
  constName: string,
  channels: ChannelIR[],
  importFrom: string,
  options: EmitOptions,
): string {
  const lines: string[] = [];
  lines.push(`// Auto-generated by contractful-gen from ${originLabel(options.specOrigin)} — DO NOT EDIT.`);
  lines.push(`// Events: ${ir.title}${ir.version ? ` (${ir.version})` : ''} · group: ${groupName}`);
  lines.push(`// Incoming messages are gated open-world; outgoing messages are validated closed-world.`);
  lines.push('');
  lines.push(`import { defineEvents, subscribe, publish, P } from ${JSON.stringify(importFrom)};`);
  lines.push('');
  lines.push(`export const ${constName} = defineEvents({`);
  lines.push(`  name: ${JSON.stringify(`${ir.title} · ${groupName}`)},`);
  lines.push(`  url: ${JSON.stringify(ir.url)},`);
  lines.push('  channels: {');
  for (const channel of channels) {
    emitChannel(lines, channel);
  }
  lines.push('  },');
  lines.push('});');
  lines.push('');
  return lines.join('\n');
}

function emitChannel(lines: string[], channel: ChannelIR): void {
  const factory = channel.direction === 'in' ? 'subscribe' : 'publish';
  const doc = channel.description ? `/** ${escapeComment(clamp(channel.description))} */\n    ` : '';

  const hasParams = channel.params.length > 0;
  const hasFields = channel.fields.length > 0;
  if (!hasParams && !hasFields) {
    lines.push(`    ${doc}${channel.name}: ${factory}(${JSON.stringify(channel.topic)}),`);
    return;
  }

  lines.push(`    ${doc}${channel.name}: ${factory}(${JSON.stringify(channel.topic)}, {`);
  if (hasParams) {
    lines.push('      params: {');
    for (const param of channel.params) emitField(lines, param);
    lines.push('      },');
  }
  if (hasFields) {
    lines.push('      fields: {');
    for (const field of channel.fields) emitField(lines, field);
    lines.push('      },');
  }
  lines.push('    }),');
}

function emitField(lines: string[], param: ParamIR): void {
  const args: string[] = [];
  if (param.required) args.push('required: true');
  if (param.tsName !== param.wireName) args.push(`as: ${JSON.stringify(param.wireName)}`);
  args.push(...schemaConstraintArgs(param.schema));
  const describe = param.schema.description ?? param.description;
  if (describe) args.push(`describe: ${JSON.stringify(clamp(describe))}`);
  lines.push(`        ${param.tsName}: P.${emitKind(param.schema)}(${formatArgs(args)}),`);
}

function chunk<T>(items: T[], size: number): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

function originLabel(origin?: string): string {
  return origin ?? 'AsyncAPI spec';
}
